CREATE TABLE TEMPLATE (
  ID RAW(16) NOT NULL,
  IS_ACTIVE NUMBER(1) DEFAULT 1 NOT NULL,
  CREATED_ON TIMESTAMP WITH TIME ZONE NOT NULL,
  UPDATED_ON TIMESTAMP WITH TIME ZONE,
  CREATED_BY VARCHAR2(100),
  UPDATED_BY VARCHAR2(100),
  CODE VARCHAR2(50 CHAR) NOT NULL,
  TITLE VARCHAR2(200 CHAR) NOT NULL
);

ALTER TABLE TEMPLATE ADD CONSTRAINT PK_TEMPLATE PRIMARY KEY (ID);

ALTER TABLE TEMPLATE ADD CONSTRAINT UK_TEMPLATE_CODE UNIQUE (CODE);

--------------------------(Data Entry)---------------------
/*******************************************************************************
** SCRIPT: POPULATE TEMPLATE TABLE (TYPES 1 & 2)
** DESCRIPTION: Dynamic Insert using SYS_GUID() to avoid hardcoded IDs
*******************************************************************************/

INSERT INTO TEMPLATE (ID, CODE, TITLE, IS_ACTIVE, CREATED_ON, UPDATED_ON)
